select employees.full_name, employees.level, departments.dept_name, departments.location, departments.budget, case when employees.job_title in ('Director', 'Intern') then 'Group A' else 'Other' end as job_title_group from employees left outer join departments on employees.dept_id = departments.id where departments.location in ('Berlin', 'Bangkok') and departments.dept_name in ('HR', 'Engineering', 'Legal') order by employees.level desc, job_title_group;
